  // the picture of a place, with nobody in it but its usual passers-by\n        const sc = SCENES[o.loc]; if (!sc) return null;\n        sky(o); const t = T(o.frame), outdoor = OUTSIDE.has(o.loc);\n        drawing(() => { DREAMING = true; drawLater = null; NO_CROWD = o.crowd === false;\n          try { const fake = {loc: o.loc, action: 'idle', x: 0, targetX: 0, travelling: false, hidden: true, pending: null, with: null};\n            sc.draw(t, +o.hour, 'idle', false, fake); if (drawLater) drawLater(t);\n            if (rainy() && outdoor) drawRain(0, 0, W, H, t, stormy() ? 140 : 90);\n            if (o.flash && stormy() && o.loc !== 'bathroom') alpha(outdoor ? .55 : .18, () => R(0, 0, W, H, '#eef4ff'));\n          } finally { DREAMING = false; NO_CROWD = false; } });\n        return cv;\n      },\n      sprite(l){  // one character or object, cut out; dx and dy place it from the layer's point\n        const t = T(l.frame); let fixed = true; sky({hour: 12});\n        drawing(() => {\n          UMB = !!l.rain;\n          if (l.kind === 'ishai'){ const fit = OUTFIT[l.outfit], keep = {shirt:C.shirt, shirtShade:C.shirtShade, pants:C.pants, inner:C.inner, pjs:C.pjs}, bed = l.pose === 'lying down', x = AX-5, y = AY-22;\n            fixed = !bed;\n            if (fit){ C.inner = fit.inner ? C.shirt : null; C.shirt = fit.shirt; C.shirtShade = shade(fit.shirt, .82); if (fit.pants) C.pants = fit.pants; C.pjs = !!fit.pjs; }\n            try { if (bed) drawIshaiBody('listening', 30, 66, t);\n              else if (['cooking','watching','waking'].includes(l.pose)) outlined(x-12, y-10, 36, 36, () => { legs(x, y, 0); drawIshaiRaw(l.pose, x, y, t); if (UMB) umbrella(x, y, t); });   // on the show a counter or a sofa hides his legs\n              else drawIshaiBody(l.pose, x, y, t, {legs: 'stand'}); } finally { Object.assign(C, keep); } }\n          else if (l.kind === 'dog') drawDog(AX-5, AY, t, l.pose, 1);\n          else if (l.kind === 'person') person(l.look, AX-5, AY-22, t, Object.assign({still: true, seed: 9, face: FACE[l.face] ?? -1}, PERSON[l.pose] || {}));\n          else { fixed = false; const p = PROPS[l.ref]; if (p) p.draw(l, t); }\n        });\n        return trim(fixed);\n      }\n    };\n  }\n  // regulars talk to themselves or to the room, on the clock: no AI, and the same line for everyone\n  const MUTTER = {\n    zelig: ['The pigeons have changed shifts again.', 'Not you. You know what you did.', 'Forty-one benches in this city. I have counted. Forty-one.', 'They moved the pond. Half a metre. Nobody admits it.', 'Yes, yes, I told him. He said no. The duck said no.', 'Tuesday. It is always a Tuesday with these people.', 'Somebody is watching this park. I can feel it in my hat.', 'Good morning, tree. Still nothing to say?'],\n    michal: ['One more set. Then one more after that.', 'Who left these weights here?', 'I said I would come three times a week. This is week two.'],\n    sivan: ['Whoever set this treadmill to twenty, please seek help.', 'Twelve more minutes. Eleven and a half.', 'Is that TV ever on anything good?'],\n    lior: ['Chapter one. Again.', 'Is the deadline a real date or a feeling?', 'Delete. Delete. Delete.'],\n    kobi0: ['Just the one tonight.', 'Same as always, thanks.', 'Quiet in here. I like it quiet.'],\n    kobi1: ['You know who else played bass? Me.', 'I am not loud. The room is small.', 'One more and I go home. That is a promise.'],\n    kobi2: ['I love this bar. I love this... what is this?', 'Where did my... no. It was here.', 'Sing with me. Nobody? Fine.', 'Tell her... tell her I was right.']\n  };\n  const MUTTER_SLOT = 35000; let mutterDone = 0;\n  setInterval(() => {\n    const now = NOW(), slot = Math.floor(now / MUTTER_SLOT), at = slot * MUTTER_SLOT + hash(slot * 17 + 3) * 12000;\n    if (slot === mutterDone || now < at || now > at + 6000 || forceLoc) return;\n    const here = Object.keys(REG).filter(id => REG[id].place === actor.loc && regHere(id) && actor.with !== id); if (!here.length) return;\n    if (SPEAKING || (SAY.who && NOW() < SAY.until) || actor.switching || actor.hidden || studioOn || showOn || callOn) return;\n    mutterDone = slot; if (hash(slot * 19 + 5) > .7) return;\n    const id = here[Math.floor(hash(slot * 23 + 7) * here.length)], list = MUTTER[id === 'kobi' ? 'kobi' + drunk() : id], line = list[Math.floor(hash(slot * 29 + 11) * list.length)];\n    showSay(id, line); holdSay(5500); Sound.say(id, line);\n  }, 1000);\n  // ================= the hosts fill the silence: every 45 s of quiet one of them says what the picture shows, no AI =================\n  // Everything is picked from the clock slot and the moments, so all viewers get the same line. Nothing here is written to the story.\n  const FILL_SLOT = 45000, FILL_QUIET = 10000;\n  const FILL = {\n    apartment: ['Apartment 4. One room, one man, one basil, no secrets.', 'Look at that windowsill. Moshe is holding the whole place together.', 'That desk has seen more revisions than a constitution.', 'The sofa, the desk, the fridge. The three stops of his daily commute.', 'Somewhere under that pile is a clean shirt. Allegedly.', 'You can tell a lot about a man by his one kitchen chair.'],\n    corridor: ['The second floor hall. Mrs. Levi can hear this through the wall, believe me.', 'That is the only hallway in Tel Aviv with its own intelligence service.', 'Apartment 4 on the left, apartment 5 on the right, and judgement in between.', 'The stairs again. The elevator is more of a rumour.', 'Listen to that echo. Nobody in this building has ever had a private conversation.', 'Second floor. Smells of soup from at least one direction.'],\n    street: [\"Herzl Street, his block. Avi's kiosk, the bus stop, the gym he thinks about.\", 'There goes the bus stop bench, the most honest seat in the city.', \"That's The Black Candle by the bench. Closed by day, like its regulars.\", 'He walks this street so often the pavement knows his shoe size.', 'Watch the kiosk. Avi sees everything and comments on all of it.', 'Traffic, pigeons, one man with a plan. Herzl Street at its finest.'],\n    shops: ['East end of Herzl. Hardware, the bank, the flowers, the crossing.', \"That's the flower shop. He has never once stopped there. We're watching that closely.\", \"He's passing Tahini Tower Savings Bank, walking a little faster, as freelancers do.\", 'Herzl Hardware. If it squeaks, they have the thing. Probably.', 'Red light at the crossing. The only thing that has ever told him no and meant it.', 'Cafe Nahat is on that corner. Keep your eyes on the corner.'],\n    west1: [\"West along Herzl now. That's PicSell, and the pharmacy coming up.\", 'Three blocks to the park. He is committing to the outdoors.', 'PicSell in the window. If it holds still, they print it.'],\n    west2: ['The Soap Opera launderette, the only place on this street with more drama than us.', \"That's the barber. He'd like a word with that hair.\", 'Middle of the walk. The makolet on the left has seen him at every hour.'],\n    west3: ['The bakery. Everyone slows down here, it is the law.', 'Second-hand bookshop on the right. He buys one and reads the back.', 'Bicycle shop, last block. The park is just ahead.'],\n    park: ['The park. One bench, one pond, one duck with a lot on its mind.', 'That tree has been here longer than the whole street.', 'Look at the pigeons. They know something, says Mr. Zelig, and I no longer argue.', 'Fresh air. We had to check the manual to see what it does.', \"There's a cat by the vending machine. It has a better routine than he does.\", 'The duck has not moved. Neither have our ratings.'],\n    bus: ['Line 88. Window seat, city going past, nobody talking. Classic Tel Aviv.', \"He's on the bus, watching the shops slide by.\", 'Nothing on a bus is ever on time except the opinions.', 'Every stop, one person gets on and one gets a seat they do not deserve.', 'That is a man on public transport, thinking about something he will never say out loud.', 'Red light. The whole bus sighs together.'],\n    taxi: ['Back seat of a taxi. The meter is the most exciting thing in shot.', \"He's watching that meter like it owes him money.\", 'The driver has opinions. You can see them from here.', 'Every red light is costing him a coffee.', 'A taxi. Somebody has money, or it is raining, or both.', 'The city going past, one shekel at a time.'],\n    market: ['Shuk Shalom. Tomatoes, shouting, and the smell of everything.', \"He's going stall to stall. This is the most decisive he gets.\", 'Every vendor here is sure you are making a mistake by walking on.', 'Look at the crowd. Nobody in that line has ever been wrong about olives.', 'The fresh juice stand. Six shekels of hope.', 'Bags in both hands soon. Watch the shoulder go.'],\n    store: ['Everything Else. Everything, except anything you can eat.', 'That wall of TVs is all showing the same thing, and it is still better than this.', 'He is browsing. Nobody in history has come out of here with only what they wanted.', 'The cashier has seen it all, mostly lamps.', 'Kitchenware aisle. A man alone with his dreams of a better pan.'],\n    gym: ['Herzl Gym. Two screens, a mirror wall, and a lot of regret.', 'That water cooler sees more action than the dumbbells.', 'Treadmills facing the television. Running, in the sense of staying exactly where you are.', 'The mirror wall. Nobody here is looking at the mirror, except everyone.', 'Somebody paid for a year in January. You can tell which.'],\n    bar: ['The Black Candle. Black brick, red neon, and nobody asking how your day was.', 'Grave Tahini on the poster. Saw them once. Still recovering.', 'Candle on the table, guitar in the air. Very moody for a Tuesday, whichever day this is.', 'That bartender has heard every sad story on Herzl Street, some of them twice.', 'Sit at a table in here long enough, you become a regular. It happened to Kobi.'],\n    cafe: ['Cafe Nahat. Corner table, soft rock, one barista seeing everything.', 'Listen to that playlist. It is 1976 in there and always will be.', 'Look at the counter. Then look at the cups. That is all I am saying.', \"That's the laptop table. Three novels have died there.\", 'Coffee, milk foam, and a lot of things nobody is saying.']\n  };\n  const FILL_DO = {\n    working: ['Eyes on the screen. Whatever that is, it needs one more change.', 'Tiny drag to the left. Tiny drag back to the right. That was ten minutes of a freelancer.', 'Look at him lean back and squint. The universal sign for version nine.', 'Save as final. Save as final two. Save as final really.', 'He stretches. He looks at the clock. He remembers what he charges.', \"That face is a man reading an email he won't answer yet.\"],\n    gaming: ['He has played this level before. It remembers him too.', 'Look at those thumbs. His best work of the week.', 'That sigh means the hero fell in the same hole.', 'One more try. It has been one more try for a while.', 'Tomer would have something to say about that score.'],\n    reading: ['Page turned. We have a page turned, everybody.', 'Is he reading, or staring at one sentence? Hard to say.', \"He's been on that paragraph long enough to rent it.\", 'Reading on a live broadcast. Bold.'],\n    watching: ['He picks a channel. He doubts the channel.', \"We're watching a man watch television. Think about that.\", 'That is the look of someone who has stopped choosing and started accepting.', 'Remote in hand, kingdom secured.'],\n    listening: ['He has the radio on and the world off.', 'Foot tapping. Slightly behind the beat, as is his way.', 'That old radio has better reception than he does.', 'Mrs. Levi can hear this too. Mrs. Levi has notes.'],\n    cooking: ['Something is happening in that pan, and he is as surprised as we are.', 'Taste, pause, more salt. Taste, pause, regret.', 'He reads the instructions after. That is the order he does things in.', 'The smell has reached apartment 5. Expect a report.'],\n    eating: ['Dinner for one, plus one dog looking heartbroken.', 'He eats like someone with a deadline and no appetite for it.', 'Chew, look at the wall, chew. Fine dining.', 'Nobody ever looks good eating on camera. Nobody.'],\n    drinking: ['A long sip, with a lot of thinking in it.', 'He holds that cup with both hands, like it might leave him.', 'Slow sip. The man has nowhere to be, or several and is avoiding them.'],\n    idle: ['He is standing there. We are all standing here with him.', 'That is the look of a man who came in here for something.', 'Scratch of the head. A plan may be forming. Do not get your hopes up.', 'Doing nothing, and frankly doing it well.', 'He looks around like someone moved everything half a metre.'],\n    walking: ['Hands in pockets, eyes on nothing. A man and his thoughts.', 'Look at that pace. Not late, not early, not sure.', 'Steady walk. Going somewhere, probably.', 'If you walk slowly enough, it counts as a decision.'],\n    exercising: ['There it is, the face of someone counting backwards.', 'Good pace. Somebody tell his knees.', 'He looked at the timer. Never look at the timer.', 'That is a lot of effort to end up in the same place.'],\n    talking: ['And a little pause there. Nobody wants to go first.', 'Listen to that silence. You could park a bus in it.', 'They have run out of words. Watch who looks away first.'],\n    phoning: ['Phone at the ear, nodding at someone who cannot see him.', 'He says yes a lot on the phone. We have noticed that.'],\n    waking: ['He is up, in the legal sense.', 'The eyes are open. The rest of him is waiting for an update.']\n  };\n  const FILL_NIGHT = ['Night shift. Still horizontal, still our favourite.', 'Listen to that. A man, a dog, a fridge humming.', 'If you are watching this at this hour, we should talk.', 'Moshe has the watch. Moshe always has the watch.', 'Nothing to report. We are reporting it anyway.', 'Tomorrow he will say he slept badly. We have the tapes.'];\n  const FILL_BATH = ['Door closed. We respect that door.', 'That door stays shut, and so does this subject.', 'A moment of privacy, the one thing we do not sell.', 'Let us all look at the door together.'];\n  const FILL_OFF = ['Still no picture. Our best people are looking at the static.', 'He is out of coverage, and I do not like how well he is doing without us.', 'Static. Honestly, a nice change of pace.', 'Wherever he is, it is not on our map.', 'We have no idea what he is doing. For once, neither does he.'];\n  const fillPick = (list, slot, k) => list[((slot * (list.length % 7 ? 7 : 5) + k) % list.length + list.length) % list.length];   // walks the whole list before repeating\n  // how long he has been at this, and how long since anyone talked to him, from the moments themselves\n  function fillFacts(){\n    const now = NOW(), done = [...TL.values()].filter(x => x.start <= now), out = [], last = done[done.length - 1];\n    if (last){ const same = x => x.ev.action === last.ev.action && (x.ev.location || 'apartment') === (last.ev.location || 'apartment');\n      let i = done.length - 1; while (i > 0 && same(done[i - 1])) i--;\n      const m = Math.round((now - done[i].start) / 60000), a = last.ev.action;\n      if (m >= 12 && !['sleeping', 'walking'].includes(a)) out.push(`That's ${m} minutes of ${a === 'idle' ? 'this' : a} now, for those keeping score.`);\n      let j = done.length - 1; while (j >= 0 && !done[j].ev.with) j--;\n      const quiet = j >= 0 ? Math.round((now - done[j].end) / 60000) : 0;\n      if (quiet >= 20) out.push(`Nobody has said a word to him in ${quiet} minutes.`); }\n    const w = WORLD && WORLD.weather; if (w) out.push(`${Math.round(w.temp)} degrees and ${w.desc} over Herzl Street${w.rain ? '. Nobody is out for fun.' : '.'}`);\n    out.push(`It's ${fmtHM.format(new Date(now))} on Herzl Street. Do you know where your basil is?`);\n    const sh = WORLD && WORLD.shabbat; if (sh && /^Fri/.test(sh.startLabel || '') && now < (sh.start || 0)) out.push(`Candles tonight at ${sh.startLabel.replace(/^\\S+\\s*/, '')}. Clock's ticking.`);\n    return out;\n  }\n  // the show's own memory, read back: today's and yesterday's summary, a sentence at a time\n  function fillRecap(){\n    const bits = o => o ? String(o.text || '').split(/(?<=[.!?])\\s+/).filter(x => x.length > 15 && x.length < 170) : [];\n    return [...bits(SUMMARY && SUMMARY.today).map(x => 'For anyone just joining: ' + x), ...bits(SUMMARY && SUMMARY.yesterday).map(x => 'Yesterday, for the record: ' + x)];\n  }\n  // who is who: the people in his life and what they hold on to\n  function fillPeople(){\n    return Object.values(CAST).filter(c => c.memory && c.memory.length > 12 && c.memory.length < 150 && (c.scenes || 0) > 0).map(c => `From the file on ${c.name}: ${c.memory}`);\n  }\n  const fillMoving = () => !!(actor.travelling || actor.pending || actor.ride || actor.rideUntil);\n  function hostFillLine(slot){\n    const a = actor.action, loc = actor.loc, r = hash(slot * 41 + 9), place = FILL[loc] || [], act = FILL_DO[a] || FILL_DO.idle;\n    if (loc === 'offscreen') return fillPick(FILL_OFF, slot, 1);\n    if (BATH.has(a)) return fillPick(FILL_BATH, slot, 2);\n    if (a === 'sleeping') return slot % 4 ? null : fillPick(FILL_NIGHT, slot / 4, 3);        // a quiet night: one line in four\n    if (fillMoving() && place.length) return fillPick(place, slot, 4);                        // on the way: they say what he is passing\n    const list = r < .3 ? place : r < .55 ? act : r < .75 ? fillFacts() : r < .92 ? fillRecap() : fillPeople();\n    return fillPick(list.length ? list : (place.length ? place : act), slot, 5);\n  }\n  // a line of the story is due soon: leave the room for it\n  const talkSoon = ms => { const now = NOW(); for (const e of TL.values()){ if (e.start > now && e.start < now + ms) return true; if (e.start <= now && e.plan.some(p => e.start + p.at + p.ms > now - 1500 && e.start + p.at < now + ms)) return true; } return false; };\n  function hostFill(force){\n    const now = NOW(), slot = Math.floor(now / FILL_SLOT), at = slot * FILL_SLOT + hash(slot * 37 + 1) * 12000;\n    if (!force && (slot === hostFill.done || now < at || now > at + 9000 || forceLoc || PREVIEW)) return false;\n    if (!force && (now - TALK_AT < FILL_QUIET || SPEAKING || (SAY.who && now < SAY.until) || actor.switching || studioOn || showOn || callOn || talkSoon(7000) || (document.hidden && !POP.on))) return false;\n    hostFill.done = slot;\n    const say = hostFillLine(slot); if (!say) return false;\n    hostLine({id: 'fill-' + slot + (force ? '-' + now : ''), t: now, who: slot % 2 ? 'oren' : 'zohar', say, host: true}, true, {at: now, ms: 0});\n    return true;\n  }\n  setInterval(hostFill, 1000);\n  // ================= overheard: now and then a passer-by's words, as a small caption. Never a name, a bubble, a voice or the chat, so nobody takes them for the cast =================\n  const OVERHEARD = {\n    street: ['...so I told him, that is not parking, that is a hobby.', '...my sister says the same about her landlord.', '...no, the other bus. The one that never comes.', '...second floor, third door, and bring the receipt.', '...I said ten minutes. It is a Tel Aviv ten minutes.', '...he is a good boy, he just bites.'],\n    shops: ['...nine shekels for one tulip? Is it a wedding?', '...the machine ate it. The whole card.', '...wait for the green, Yonatan. Wait.', '...I only came in for a screw.', '...she never said yes, she said we will see.'],\n    west1: ['...print it bigger. No, smaller. Bigger.', '...the pharmacist knows everything about this street.', '...it was a joke shirt, and my mother wore it to a wedding.'],\n    west2: ['...same haircut as last time, but happier.', '...somebody took my socks out and left them on top.', '...closed for inventory. There are four things in there.'],\n    west3: ['...still warm, smell it, go on.', '...first edition. Of what, he would not say.', '...a bike that old has opinions.'],\n    park: ['...the duck is new. I am telling you.', '...three kilometres. Okay, two. Okay, to the bench.', '...he says the same to the pigeons, I heard him.', '...leave the cat, the cat has a job.'],\n    market: ['...how much? For that? I knew your father!', '...two kilos, and not from the top, I can see the top.', '...taste it, taste it, you are insulting me.', '...the good ones are in the back, always in the back.', '...who sells a cucumber like that on a Friday?', '...yalla, yalla, closing soon, take three.'],\n    store: ['...it is the same lamp, it just costs more.', '...does it come in a colour that is not grey?', '...I came for batteries. Look at this trolley.'],\n    gym: ['...one more. One more. That was one more.', '...my trainer says it is water weight.', '...is anyone using this? I am asking the machine.'],\n    bar: ['...the bassist quit, and then the band quit the bassist.', '...he is not my ex, he is my former mistake.', '...turn it up, nobody here is talking anyway.'],\n    cafe: ['...I am not writing, I am researching.', '...oat, soy, or the other one that has feelings?', '...we should really get a proper office.', '...she said she would call, so I moved to a closer table.'],\n    bus: ['...next stop? No, the one after the one after.', '...this seat is taken by my bag.', '...I have been on this line since 1994.']\n  };\n  const OVER_SLOT = 240000, OVER_MS = 6500; let overUntil = 0, overDone = 0;\n  function overhear(force){\n    const now = NOW(), slot = Math.floor(now / OVER_SLOT), at = slot * OVER_SLOT + hash(slot * 43 + 2) * 150000, list = OVERHEARD[actor.loc], h = hourNow();\n    if (!force && (slot === overDone || now < at || now > at + 12000 || !list || h < 7 || h >= 23 || forceLoc || PREVIEW)) return false;\n    if (!list || (!force && (now - TALK_AT < 6000 || SPEAKING || (SAY.who && now < SAY.until) || actor.switching || actor.hidden || actor.with || studioOn || showOn || callOn || talkSoon(8000)))) return false;\n    overDone = slot; if (!force && hash(slot * 47 + 1) > .6) return false;                    // most slots pass by without